import{_ as r,a0 as s,w as p,s as f,ao as l,I as o,x as n,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何給任意一款 Linux 發行版添加漂亮的字體 | LCTT x X-CMD","titleTemplate":false,"description":"如何給任意一款 Linux 發行版添加漂亮的字體 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何給任意一款 Linux 發行版添加漂亮的字體 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何給任意一款 Linux 發行版添加漂亮的字體 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/How to Add Beautiful Fonts to Any Linux Distribution","title":"如何給任意一款 Linux 發行版添加漂亮的字體","tag":"201405","desc":""},"relativePath":"201405/How to Add Beautiful Fonts to Any Linux Distribution.md","filePath":"[post].md"}'),u={name:"201405/How to Add Beautiful Fonts to Any Linux Distribution.md"};function d(m,i,y,b,h,x){const t=s("Link");return p(),f("div",null,[i[16]||(i[16]=l(`<h1 id="如何給任意一款-linux-發行版添加漂亮的字體" tabindex="-1">如何給任意一款 Linux 發行版添加漂亮的字體 <a class="header-anchor" href="#如何給任意一款-linux-發行版添加漂亮的字體" aria-label="Permalink to “如何給任意一款 Linux 發行版添加漂亮的字體”">​</a></h1><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Add-Beautiful-Fonts-to-Any-Linux-Distribution-434835-2.jpg" alt=""></p><p><strong>接下來的教程將指導所有 Linux 用户怎麼簡單的將漂亮的字體添加到自己的操作系統。我們已經為 Debian、Arch Linux、openSUSE、Slackware 和 Fedora 發行版編寫了詳細的介紹。</strong></p><p>正如許多用户所知，幾乎所有基於 Linux 的操作系統主要缺點就是默認選擇的字體並不令終端用户滿意，尤其是那些從 Windows 或者 Mac OS X 等操作系統遷移過來的用户。</p><p>除了使用自己的一套字體的Ubuntu，從一開始就看起來就相當漂亮，其它所有 Linux 發行版都有字體醜陋的缺點。正因如此，許多用户試圖創建一種新的方法來增強文字在各個發行版中渲染效果。</p><p>這就是 Infinality 項目產生的原因，其主要目的是通過添加補丁來為使用任何基於 Linux 操作系統的用户提供最好的字體渲染效果。</p><h3 id="infinality-for-arch-linux" tabindex="-1">Infinality for Arch Linux <a class="header-anchor" href="#infinality-for-arch-linux" aria-label="Permalink to “Infinality for Arch Linux”">​</a></h3><ol><li><p>將infinality-bundle，infinality-bundle-multilib （用於使用64位系統的用户）和infinality-bundle-fonts倉庫添加到你的 /etc/pacman.conf文件中：</p><pre><code> [infinality-bundle]
 Server = http://bohoomil.com/repo/$arch

 [infinality-bundle-multilib]
 Server = http://bohoomil.com/repo/multilib/$arch

 [infinality-bundle-fonts]
 Server = http://bohoomil.com/repo/fonts
</code></pre></li><li><p>執行 sudo pacman -Syu 命令用來刷新倉庫，然後運行</p><pre><code> sudo pacman -S infinality-bundle infinality-bundle-multilib ibfonts-meta-extended （用於64位系統） 

 sudo pacman -S infinality-bundle ibfonts-meta-extended （用於32位系統）
</code></pre></li><li><p>當被詢問是否替換 fontconfig 軟件包的 freetype2 時，回答YES。完成後重啓你的計算機。</p></li></ol><h3 id="infinality-for-fedora" tabindex="-1">Infinality for Fedora <a class="header-anchor" href="#infinality-for-fedora" aria-label="Permalink to “Infinality for Fedora”">​</a></h3><ol><li><p>在終端窗口中執行如下命令</p><pre><code> sudo rpm -Uvh http://www.infinality.net/fedora/linux/infinality-repo-1.0-1.noarch.rpm
 sudo yum install freetype-infinality fontconfig-infinality
</code></pre></li><li><p>重啓你的機器。</p></li></ol><h3 id="infinality-for-opensuse" tabindex="-1">Infinality for openSUSE <a class="header-anchor" href="#infinality-for-opensuse" aria-label="Permalink to “Infinality for openSUSE”">​</a></h3><ol><li><p>添加 Infinality 官方倉庫：</p><pre><code> http://download.opensuse.org/repositories/home:/namtrac:/subpixel/openSUSE_13.1/
</code></pre></li></ol><p>打開YaST中的庫選項卡，選擇namtrac:subpixel倉庫，並打擊“切換系統包的版本到這個倉庫”。</p><ol start="2"><li><p>標記 namtrac:subpixel 中所有還沒有安裝的包來進行安裝，然後從 openSUSE 官方軟件倉庫中安裝 fontconfig-infinality 包。</p></li><li><p>在字體設置選項裏將 Subpixel Hinting 選擇為“使用系統設置”，或者設置為帶有微調的 RGB 順序。重啓你的系統。</p></li></ol><h3 id="infinality-for-slackware" tabindex="-1">Infinality for Slackware <a class="header-anchor" href="#infinality-for-slackware" aria-label="Permalink to “Infinality for Slackware”">​</a></h3>`,15)),o("p",null,[i[1]||(i[1]=n("詳細的安裝指南：",-1)),e(t,{href:"http://someslack.wordpress.com/infinality-on-slackware/"},{default:a(()=>[...i[0]||(i[0]=[n("http://someslack.wordpress.com/infinality-on-slackware/",-1)])]),_:1})]),i[17]||(i[17]=l(`<h3 id="infinality-for-debian" tabindex="-1">Infinality for Debian <a class="header-anchor" href="#infinality-for-debian" aria-label="Permalink to “Infinality for Debian”">​</a></h3><ol><li><p>在終端中執行下面的命令（一個一個執行，每一行之後敲擊回車）：</p><pre><code> echo “deb http://ppa.launchpad.net/no1wantdthisname/ppa/ubuntu raring main” | sudo tee /etc/apt/sources.list.d/infinality.list
 echo “deb-src http://ppa.launchpad.net/no1wantdthisname/ppa/ubuntu raring main” | sudo tee -a /etc/apt/sources.list.d/infinality.list
 sudo apt-key adv --keyserver keyserver.ubuntu.com --recv-keys E985B27B
</code></pre></li><li><p>執行以下命令來升級你的系統並安裝 Infinality 包：</p><pre><code> sudo apt-get update
 sudo apt-get upgrade
 sudo apt-get install fontconfig-infinality
</code></pre></li><li><p>重啓你的計算機。</p></li></ol>`,2)),o("p",null,[i[3]||(i[3]=n("對於任何文中沒有提到的其它 Linux 發行版，請使用官方的介紹：",-1)),e(t,{href:"https://github.com/Infinality/fontconfig-infinality/tree/master/infinality"},{default:a(()=>[...i[2]||(i[2]=[n("https://github.com/Infinality/fontconfig-infinality/tree/master/infinality",-1)])]),_:1}),i[4]||(i[4]=n("。跟以往一樣，當你使用本教程過程中遇到任何問題都可以在下面評論，不要猶豫。",-1))]),i[18]||(i[18]=o("hr",null,null,-1)),o("p",null,[i[6]||(i[6]=n("via: ",-1)),e(t,{href:"http://news.softpedia.com/news/How-to-Add-Beautiful-Fonts-to-Any-Linux-Distribution-434835.shtml"},{default:a(()=>[...i[5]||(i[5]=[n("http://news.softpedia.com/news/How-to-Add-Beautiful-Fonts-to-Any-Linux-Distribution-434835.shtml",-1)])]),_:1})]),o("p",null,[i[9]||(i[9]=n("譯者：",-1)),e(t,{href:"https://github.com/scusjs"},{default:a(()=>[...i[7]||(i[7]=[n("SCUSJS",-1)])]),_:1}),i[10]||(i[10]=n(" 校對：",-1)),e(t,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...i[8]||(i[8]=[n("Caroline",-1)])]),_:1})]),o("p",null,[i[13]||(i[13]=n("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[11]||(i[11]=[n("LCTT",-1)])]),_:1}),i[14]||(i[14]=n(" 原創翻譯，",-1)),e(t,{href:"http://linux.cn/"},{default:a(()=>[...i[12]||(i[12]=[n("Linux中國",-1)])]),_:1}),i[15]||(i[15]=n(" 榮譽推出",-1))])])}const L=r(u,[["render",d]]);export{w as __pageData,L as default};
